<?php $pageHeading = PublicTheme::text($settings, 'prestasi'); include __DIR__ . '/banner.php'; $achievements = $data['prestasi'] ?? []; ?>
<section class="next-shell next-archive"><form action="/prestasi" method="get" class="next-archive-toolbar"><label for="next-achievement-filter"><?= e(PublicTheme::text($settings, 'category')) ?></label><select id="next-achievement-filter" name="kategori"><option value=""><?= e(PublicTheme::text($settings, 'all_categories')) ?></option><?php foreach (['Sekolah','Guru','Murid'] as $category): ?><option value="<?= e($category) ?>" <?= ($data['current_category'] ?? '') === $category ? 'selected' : '' ?>><?= e($category) ?></option><?php endforeach; ?></select><button class="next-button next-button--primary" type="submit"><?= e(PublicTheme::text($settings, 'filter')) ?></button></form>
<div class="next-archive-grid"><?php foreach ($achievements as $item): ?><article class="next-archive-card"><a class="next-archive-image" href="/prestasi/<?= (int) $item['id'] ?>"><?php if (!empty($item['image'])): ?><img src="/storage/<?= e($item['image']) ?>" alt="<?= e($item['title']) ?>" loading="lazy"><?php endif; ?></a><div class="next-archive-body"><p class="next-byline"><?= e($item['category']) ?><?php if (!empty($item['date'])): ?> · <?= e(date('d M Y', strtotime($item['date']))) ?><?php endif; ?></p><h2><a href="/prestasi/<?= (int) $item['id'] ?>"><?= e($item['title']) ?></a></h2><p><?= e(PublicTheme::summary($item['description'] ?? '')) ?></p></div></article><?php endforeach; ?></div><?php if (!$achievements): ?><p class="next-empty"><?= e(PublicTheme::text($settings, 'empty')) ?></p><?php endif; ?></section>
